  ('niidaleeng', 'niidaleeng', '', '', '', 'Grundwortschatz Wienerisch', 'niederlegen', '[{"kategorie": "wörtlich", "text": "\"etwas auf den Boden legen\" (Kompositum aus dem abtrennbaren Präfix \"nieder\"=\"nach unten\" und \"legen\"=\"setzen\")"}, {"kategorie": "allg.", "text": "\"etwas nach unten legen\", beiseite legen, weglegen"}, {"kategorie": "fig.", "text": "ein Amt zurücklegen, abtreten, die Arbeit niederlegen, streiken, (auch): \"die Waffen niederlegen\", [[einen Kranz niederlegen]]"}, {"kategorie": "hist.", "text": "etwas niederschreiben, zu Papier bringen, schriftlich festhalten, dokumentieren"}, {"kategorie": "Gaunersprache", "text": "ein Geständnis ablegen, [[abladen]], [[zwitschern]], [[singen]]"}, {"kategorie": "reflexiv", "text": "sich niederlegen, zu Bett gehen, sich in die Horizontale begeben, ein Schläfchen machen"}, {"kategorie": "", "text": "\"sich schlafen legen\", \"sich zur Ruhe begeben\", \"zu Bett gehen\", \"sich aufs Ohr hauen\""}, {"kategorie": "poetisch für", "text": "friedlich entschlafen, sterben, das Zeitliche segnen, [[haamgee]], [[den]] Löffel abgeben, [[ein]] Bankerl reißen, [[die]] Patschen strecken, [[sich]] die Erdäpfel von unten anschauen"}, {"kategorie": "scherzhaft für", "text": "\"sich vor Erstaunen/Schreck/Überforderung hinlegen müssen\", \"aus allen Wolken fallen\", \"vor Schreck in die Knie gehen\", \"den Boden unter den Füßen verlieren\", \"nicht mehr wissen, wo oben und unten ist\""}]'::jsonb, 'Waunn de Glockn leit, muass jeeda in Schdifd niidaleeng!'),
  ('haamgee', 'haamgee', '', '', '', 'Grundwortschatz Wienerisch', 'heimgehen', '[{"kategorie": "wörtlich", "text": "\"nach Hause gehen\" (Kompositum aus dem Partikel/Verbzusatz \"heim\"=\"nach Hause\" und \"gehen\"=\"abgehen\")"}, {"kategorie": "allg.", "text": "\"nach Hause gehen\", \"den Heimweg antreten\", \"sich auf den Weg nach Hause machen\", \"heimwärts gehen\""}, {"kategorie": "poetisch für", "text": "\"sterben\", \"den letzten Weg antreten\", [[sich]] niederlegen, [[die]] Patschen aufstellen, [[den]] Löffel abgeben, [[min Aanasiibzga haamfoan]]"}]'::jsonb, 'si niidaleeng'),
  ('schdrichkotz', 'Schdrichkotz', 'die', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Strichkatze', '[{"kategorie": "wörtlich", "text": "\"Mädchen, das auf den Strich geht\" (Determinativkompositum aus \"Strich\"=\"Straßenstrich\" und \"Katze\"=\"scharfe Braut\")"}, {"kategorie": "allg.", "text": "Strichmädchen, Callgirl, Sexkätzchen, Laufmädchen, [[Hackenbraut]], [[Pferderl]], [[Drescherl]], [[Schickserl]], [[Sittich]], [[Betthaserl]]"}]'::jsonb, 'I waass, si is a Schdrichkotz - owa si hod an bessan Karakta ois dei Oide!'),
