  ('sumpa', 'Sumpa', 'der', '', '', 'Grundwortschatz Wienerisch', 'Sumper', '[{"kategorie": "wörtlich", "text": "\"Sumper\" (vom mittelhochdeutschen \"sumber\" = \"Geflecht\")"}, {"kategorie": "allg.", "text": "\"großer geflochtener Strohkorb\", Holzkorb, Brennholzkorb"}, {"kategorie": "Musik, vom mittelhochdeutschen \"sumber\" = \"Handtrommel\"", "text": "Handtrommel, Rahmentrommel, Tamburin"}, {"kategorie": "fig., vom mittelhochdeutschen \"sumbern\" = \"faulen\" bzw. \"in Fäulnis übergehen\"", "text": "Langweiler, \"Schlaftablette\", \"Couchpotato\", [[Wiaschdlwäama]], [[Sumpara]], [[tooda]] Tiroola, [[Laumlackl]]"}]'::jsonb, 'Da groosse Sumpa vom Groossvoodan schdeed no imma neeman Oofn - raundvoi mit Brennhoiz und oide Gschichdn!'),
