  ('pissn', 'pissn', '', '', '', 'Grundwortschatz Wienerisch', 'pissen', '[{"kategorie": "wörtlich", "text": "\"pissen\" (vom lateinischen \"pissiare\"=\"pischen\")"}, {"kategorie": "allg.", "text": "urinieren, Wasser lassen, [[Pipii mochn]], [[Luluu mochn]], [[pinkln]], [[piisln]], [[brunzn]], [[schiffn]], [[in]] Kaschbal schneizn"}]'::jsonb, 'Pissn tuan nua de Preissn - bei uns geed ma in Kaschbal schneizn!'),
