  ('schbeiskoatn', 'Schbeiskoatn', 'die', '', '', 'Grundwortschatz Wienerisch', 'Speisekarte', '[{"kategorie": "wörtlich", "text": "\"Speisekarte\" (Determinativkompositum aus \"Speise\"=\"Mahlzeit\" und \"Karte\"=\"Liste\")"}, {"kategorie": "Gastronomie", "text": "\"Menükarte\", \"Speisenliste\", \"Restaurantkarte\""}, {"kategorie": "Gaunersprache", "text": "Vorstrafenregister, Vorstrafenakte, Vorstrafenliste, Liste an Vorverurteilungen"}]'::jsonb, 'Schau ma hoit ind Schbeiskoatn - iagendwos weama schoo findn, wos uns ned glei umbringd!'),
